#include "oa_native_dof.h"
#include <math.h>
#include <string.h>
extern GLuint oa_post_program(const char *,const char *);
static const char *vs="#version 300 es\nvoid main(){vec2 p=vec2(float((gl_VertexID<<1)&2),float(gl_VertexID&2));gl_Position=vec4(p*2.-1.,0.,1.);}";
static const char *fuzz_fs=
"#version 300 es\nprecision highp float;precision highp int;uniform sampler2D depthTex;uniform vec2 halfExtent,inverseDepth;uniform vec4 config;out vec4 o;void main(){"
"vec2 nativeUV=vec2(gl_FragCoord.x,halfExtent.y-gl_FragCoord.y)/halfExtent;ivec2 n=textureSize(depthTex,0);ivec2 q=clamp(ivec2(floor(nativeUV*vec2(n))),ivec2(0),n-1);q.y=n.y-1-q.y;float d=texelFetch(depthTex,q,0).r;if(d==0.)d=1.;"
"float z=1./(inverseDepth.x*d+inverseDepth.y);float nz=z*config.w;float coc=min(max((nz-config.x)*config.y,0.),config.z);float farCoc=nz>config.x?coc:0.;o=vec4(farCoc,nz,farCoc,farCoc);}";
static const char *effect_fs=
"#version 300 es\nprecision highp float;precision highp int;uniform sampler2D sceneTex,fuzzTex;uniform vec2 extent,tapScale;out vec4 o;"
"vec4 scene(vec2 uv){return texture(sceneTex,vec2(uv.x,1.-uv.y));}vec4 fuzz(vec2 uv){return texture(fuzzTex,vec2(uv.x,1.-uv.y));}"
"const vec2 taps[16]=vec2[16](vec2(.402850002,.0401399992),vec2(.127312005,.372079015),vec2(-.287164003,-.523500025),vec2(-.200276002,.55390799),vec2(.177846998,.554831028),vec2(-.49496901,.287847012),vec2(.314258993,.663151979),vec2(.438827008,-.395498991),vec2(-.542695999,.512251973),vec2(.39943099,-.649686992),vec2(-.595748007,-.0997679979),vec2(-.141366005,.0911030024),vec2(.721309006,.206925005),vec2(-.434475988,-.411615998),vec2(.715196013,-.266535997),vec2(.178103998,.747582972));"
"void main(){vec2 uv=vec2(gl_FragCoord.x,extent.y-gl_FragCoord.y)/extent;vec4 center=fuzz(uv);float reduce=center.z>0.?.5:1.;vec3 total=scene(uv).rgb;float weight=1.;for(int i=0;i<16;i++){vec2 q=uv+center.x*(tapScale*taps[i]);vec4 f=fuzz(q);float w=f.x*(f.y<center.y?reduce:1.);total=scene(q).rgb*w+total;weight=weight+w;}o=vec4(total/weight,center.x);}";
void oa_native_dof_default_params(oa_native_dof_params *out){out->far_start_world=9974.3115234375f;out->far_range_world=20001.f;out->max_alpha=.699999988079071f;out->depth_storage_scale=1.9073486328125e-6f;}
int oa_native_dof_inverse_depth(float out[2],const float m[16]){double s2=0,a=0,b,s;int j;if(!out||!m)return 0;for(j=0;j<3;j++){s2+=(double)m[j*4+3]*m[j*4+3];a+=(double)m[j*4+2]*m[j*4+3];}if(!(s2>1e-12)||!isfinite(s2))return 0;s=sqrt(s2);a/=s2;b=((double)m[14]-a*m[15])/(2*s);if(!(b<0)||!isfinite(b))return 0;out[0]=(float)(1/b);out[1]=(float)(-((a+1)*.5)/b);return isfinite(out[0])&&isfinite(out[1]);}
static int target(GLuint *tex,GLuint *fbo,int w,int h){glGenTextures(1,tex);glBindTexture(GL_TEXTURE_2D,*tex);glTexImage2D(GL_TEXTURE_2D,0,GL_RGBA8,w,h,0,GL_RGBA,GL_UNSIGNED_BYTE,0);glTexParameteri(GL_TEXTURE_2D,GL_TEXTURE_MIN_FILTER,GL_LINEAR);glTexParameteri(GL_TEXTURE_2D,GL_TEXTURE_MAG_FILTER,GL_LINEAR);glTexParameteri(GL_TEXTURE_2D,GL_TEXTURE_WRAP_S,GL_CLAMP_TO_EDGE);glTexParameteri(GL_TEXTURE_2D,GL_TEXTURE_WRAP_T,GL_CLAMP_TO_EDGE);glGenFramebuffers(1,fbo);glBindFramebuffer(GL_FRAMEBUFFER,*fbo);glFramebufferTexture2D(GL_FRAMEBUFFER,GL_COLOR_ATTACHMENT0,GL_TEXTURE_2D,*tex,0);return glCheckFramebufferStatus(GL_FRAMEBUFFER)==GL_FRAMEBUFFER_COMPLETE;}
void oa_native_dof_close(oa_native_dof *p){if(!p)return;if(p->fuzz_tex)glDeleteTextures(1,&p->fuzz_tex);if(p->effect_tex)glDeleteTextures(1,&p->effect_tex);if(p->fuzz_fbo)glDeleteFramebuffers(1,&p->fuzz_fbo);if(p->effect_fbo)glDeleteFramebuffers(1,&p->effect_fbo);if(p->fuzz_program)glDeleteProgram(p->fuzz_program);if(p->effect_program)glDeleteProgram(p->effect_program);if(p->vao)glDeleteVertexArrays(1,&p->vao);if(p->linear_sampler)glDeleteSamplers(1,&p->linear_sampler);memset(p,0,sizeof(*p));}
int oa_native_dof_open(oa_native_dof *p,int w,int h){if(!p)return 0;memset(p,0,sizeof(*p));if(w<2||h<2)return 0;p->w=w;p->h=h;p->half_w=w/2;p->half_h=h/2;p->fuzz_program=oa_post_program(vs,fuzz_fs);p->effect_program=oa_post_program(vs,effect_fs);if(!p->fuzz_program||!p->effect_program)goto fail;if(!target(&p->fuzz_tex,&p->fuzz_fbo,p->half_w,p->half_h)||!target(&p->effect_tex,&p->effect_fbo,w,h))goto fail;glGenVertexArrays(1,&p->vao);glGenSamplers(1,&p->linear_sampler);glSamplerParameteri(p->linear_sampler,GL_TEXTURE_MIN_FILTER,GL_LINEAR);glSamplerParameteri(p->linear_sampler,GL_TEXTURE_MAG_FILTER,GL_LINEAR);glSamplerParameteri(p->linear_sampler,GL_TEXTURE_WRAP_S,GL_CLAMP_TO_EDGE);glSamplerParameteri(p->linear_sampler,GL_TEXTURE_WRAP_T,GL_CLAMP_TO_EDGE);p->ready=1;glBindFramebuffer(GL_FRAMEBUFFER,0);return 1;fail:oa_native_dof_close(p);glBindFramebuffer(GL_FRAMEBUFFER,0);return 0;}
GLuint oa_native_dof_render_constants(oa_native_dof *p,GLuint scene,GLuint depth,const float inv[2],const oa_native_dof_params *cfg){oa_native_dof_params def;float c[4];if(!p||!p->ready||!scene||!depth||!inv)return 0;if(!cfg){oa_native_dof_default_params(&def);cfg=&def;}if(!(cfg->far_range_world>0&&cfg->depth_storage_scale>0&&cfg->max_alpha>=0))return 0;c[0]=cfg->far_start_world*cfg->depth_storage_scale;c[1]=1.f/(cfg->far_range_world*cfg->depth_storage_scale);c[2]=cfg->max_alpha;c[3]=cfg->depth_storage_scale;glDisable(GL_DEPTH_TEST);glDepthMask(GL_FALSE);glDisable(GL_STENCIL_TEST);glDisable(GL_BLEND);glDisable(GL_CULL_FACE);glDisable(GL_SCISSOR_TEST);glDisable(GL_DITHER);glColorMask(GL_TRUE,GL_TRUE,GL_TRUE,GL_TRUE);glBindVertexArray(p->vao);glBindFramebuffer(GL_FRAMEBUFFER,p->fuzz_fbo);glViewport(0,0,p->half_w,p->half_h);glUseProgram(p->fuzz_program);glUniform2f(glGetUniformLocation(p->fuzz_program,"halfExtent"),(float)p->half_w,(float)p->half_h);glUniform2fv(glGetUniformLocation(p->fuzz_program,"inverseDepth"),1,inv);glUniform4fv(glGetUniformLocation(p->fuzz_program,"config"),1,c);glActiveTexture(GL_TEXTURE0);glBindSampler(0,0);glBindTexture(GL_TEXTURE_2D,depth);glUniform1i(glGetUniformLocation(p->fuzz_program,"depthTex"),0);glDrawArrays(GL_TRIANGLES,0,3);glBindFramebuffer(GL_FRAMEBUFFER,p->effect_fbo);glViewport(0,0,p->w,p->h);glUseProgram(p->effect_program);glUniform2f(glGetUniformLocation(p->effect_program,"extent"),(float)p->w,(float)p->h);glUniform2f(glGetUniformLocation(p->effect_program,"tapScale"),6.f/p->w,6.f/p->h);glActiveTexture(GL_TEXTURE0);glBindTexture(GL_TEXTURE_2D,scene);glBindSampler(0,p->linear_sampler);glUniform1i(glGetUniformLocation(p->effect_program,"sceneTex"),0);glActiveTexture(GL_TEXTURE1);glBindTexture(GL_TEXTURE_2D,p->fuzz_tex);glBindSampler(1,p->linear_sampler);glUniform1i(glGetUniformLocation(p->effect_program,"fuzzTex"),1);glDrawArrays(GL_TRIANGLES,0,3);glBindSampler(0,0);glBindSampler(1,0);glActiveTexture(GL_TEXTURE0);return p->effect_tex;}
GLuint oa_native_dof_render(oa_native_dof *p,GLuint scene,GLuint depth,const float vp[16],const oa_native_dof_params *params){float inv[2];if(!oa_native_dof_inverse_depth(inv,vp))return 0;return oa_native_dof_render_constants(p,scene,depth,inv,params);}
